<script setup>
import { onMounted, ref, watch } from 'vue'
import { useRoute } from 'vue-router'
import { api, errorMessage } from '../api.js'
import { useAuth } from '../stores/auth.js'
import { formatTime } from '../time.js'
import StatusBadge from '../components/StatusBadge.vue'
import PaginationBar from '../components/PaginationBar.vue'
const route = useRoute(), auth = useAuth(), data = ref({ content: [], page: 0, totalPages: 0, totalElements: 0 }), busy = ref(false), error = ref('')
async function load(page = 0) { busy.value = true; error.value = ''; try { const path = route.query.reminderId ? `/email-logs/${encodeURIComponent(route.query.reminderId)}` : '/reminders/history'; data.value = (await api.get(path, { params: { page, size: 20 } })).data } catch (e) { error.value = errorMessage(e) } finally { busy.value = false } }
onMounted(() => load()); watch(() => route.query.reminderId, () => load())
</script>
<template><div class="page-heading"><div><span class="eyebrow">EVERY ATTEMPT, ACCOUNTED FOR</span><h1>Email history</h1><p>A clear record of what happened, and when.</p></div><RouterLink v-if="route.query.reminderId" to="/history" class="button ghost">View all history</RouterLink></div><p class="notice info">“SMTP accepted” confirms submission to the email provider, not inbox delivery. “Needs review” means acceptance was uncertain; automatic resending stopped.</p><p v-if="error" class="notice error" role="alert">{{ error }}</p><section class="panel"><div class="panel-heading"><div><h2>{{ route.query.reminderId ? `History for reminder #${route.query.reminderId}` : 'Delivery attempts' }}</h2><p>Newest attempts first · displayed in {{ auth.user?.timeZone }}</p></div><button class="button ghost small" :disabled="busy" @click="load(data.page)">{{ busy ? 'Loading…' : '↻ Refresh' }}</button></div><div v-if="!busy && !data.content.length" class="empty-state large"><span>↗</span><h3>No attempts yet.</h3><p>Once a reminder is processed, its history will appear here.</p></div><div v-else class="table-scroll"><table><thead><tr><th>Reminder / recipient</th><th>Attempt</th><th>Started / completed</th><th>Outcome</th><th>Details</th></tr></thead><tbody><tr v-for="log in data.content" :key="log.id"><td><strong>{{ log.reminderTitle }}</strong><small>{{ log.recipientEmail }}</small><small>#{{ log.reminderId }}</small></td><td>{{ log.attemptNumber }}</td><td>{{ formatTime(log.startedAt, auth.user?.timeZone) }}<small>{{ formatTime(log.completedAt, auth.user?.timeZone) }}</small></td><td><StatusBadge :status="log.status" /></td><td class="reason-cell">{{ log.failureReason || (log.status === 'SMTP_ACCEPTED' ? 'Accepted by SMTP server' : 'Awaiting outcome') }}</td></tr></tbody></table></div><PaginationBar :page="data.page" :total-pages="data.totalPages" :total-elements="data.totalElements" :busy="busy" @change="load" /></section></template>
